/** Refuses an expectation a JavaScript caller left incomplete, before it can match anything. */
function checkExpected(expect: ExpectedPayment) {
  if (typeof expect !== "object" || expect === null)
    throw new TypeError("expect must describe the payment");
  for (const field of ["recipient", "asset", "amount", "reference"] as const)
    if (typeof expect[field] !== "string" || expect[field] === "")
      throw new TypeError(`expect.${field} must be a non-empty string`);
  if (expect.chain !== undefined && (typeof expect.chain !== "string" || expect.chain === ""))
    throw new TypeError("expect.chain must be a non-empty string when given");
  if (expect.memo !== undefined && typeof expect.memo !== "string")
    throw new TypeError("expect.memo must be a string when given");
  if (expect.confidential !== undefined && typeof expect.confidential !== "boolean")
    throw new TypeError("expect.confidential must be a boolean when given");
}

/** The receipt's opening, when it is the settled event the receipt names and commits its evidence. */
function settledOpening(receipt: Receipt) {
  const opening = utf8ToBytes(receipt.opening);
  const { fields } = decodeAuditOpening(opening);
  if (
    fields.agentId !== receipt.agent_id ||
    fields.resourceId !== receipt.correlation_id ||
    fields.action !== receipt.action ||
    fields.createdAt !== receipt.created_at
  )
    throw new NoteError("the opening does not describe this receipt");
  if (receipt.action !== SETTLED_EVENT)
    throw new NoteError(`receipt is for ${receipt.action}, not the settled event ${SETTLED_EVENT}`);
  if (fields.evidenceHash !== bytesToHex(sha256(utf8ToBytes(receipt.evidence))))
    throw new NoteError("the evidence is not what the opening committed");
  return { opening, fields };
}

/**
 * A tile at its width in the trusted tree. A partial tile the log collected since is the prefix of
 * its full tile, which tlog-tiles lets a client read instead.
 */
async function provenTile(readTile: TileReader, tile: TileId, size: bigint): Promise<Uint8Array> {
  const width = tileWidth(tile, size);
  const path = tilePath(tile, width);
  const row = await readTile(path);
  if (row) {
    if (row.length !== width * HASH_SIZE) throw new NoteError(`tile ${path} has the wrong size`);
    return row;
  }
  const full = width < TILE_WIDTH ? await readTile(tilePath(tile, TILE_WIDTH)) : null;
  // The trusted tree commits to this tile, so its absence is the log's serving, not the receipt.
  if (!full)
    throw new LogUnavailableError(
      `the log did not serve tile ${path}, which its tree of size ${size} must contain`,
    );
  if (full.length !== FULL_TILE) throw new NoteError(`tile ${path} has the wrong size`);
  return full.subarray(0, width * HASH_SIZE);
}

